<?php ac_hero('Document inspector','SSOT Library','Inspect machine-readable source documents, metadata, maintenance posture, summaries, and module links.'); ?><section class="card-grid"><?php foreach(ac_ssot_files() as $file){ $d=ac_ssot_json($file); echo '<article class="card"><code>'.ac_e($file).'</code><h3>'.ac_e(ac_doc_title($d,$file)).'</h3><p>'.ac_e(ac_doc_summary($d)).'</p><p>'.ac_pill($d['timeline_classification']??'needs review','timeline').' '.ac_pill($d['maintenance']['status']??'source','status').'</p><a class="button" href="?page=records">View records</a></article>'; } ?></section>